// The event listener has to be registered as soon as possible, before the
// browser discovering the availability of a Service Worker and a manifest.
window.addEventListener('beforeinstallprompt', function (e) {
    // Prevent Chrome 76 and later from showing the mini-infobar
    e.preventDefault();
    // Stash the event so it can be triggered later.
    window['FluidTopicsPwaBeforeInstallPrompt'] = e;
});

window['loadExternalScript'] = async function (url, module) {
    if (document.head.querySelector(`[src="${ url }"]`)) {
        return
    }
    const script = document.createElement("script")
    script.src = url
    if (module) {
        script.type = "module"
    }

    return new Promise((resolve, reject) => {
        script.onload = (e) => {
            script.setAttribute("loaded", "true")
            resolve()
        }
        script.onerror = (e) => {
            script.setAttribute("loaded", "true")
            reject("Could not load external script " + url)
        }
        document.head.append(script)
    })
};
